To ensure the system is both robust and adaptable to future business needs, I have updated the schema to include a dedicated **`users`** table and introduced **polymorphic relations** and **JSON metadata**. 

This version restores the critical availability logic (schedules and breaks) while providing the requested flexibility to handle various bookable resources (staff, rooms, or equipment) without significant modifications.

```python
def generate_extensible_booking_system_migrations():
    """
    Returns a dictionary of Laravel migrations including a managed users table,
    recurring availability patterns, and a polymorphic exclusion system.
    """
    migrations = {}

    # 1. Roles Table
    migrations["create_roles_table"] = """
    Schema::create('roles', function (Blueprint $table) {
        $table->id();
        $table->string('slug')->unique(); // 'admin', 'staff', 'customer'
        $table->string('display_name');
        $table->timestamps();
    });
    """

    # 2. Users Table
    migrations["create_users_table"] = """
    Schema::create('users', function (Blueprint $table) {
        $table->id();
        $table->foreignId('role_id')->constrained();
        $table->string('name');
        $table->string('email')->unique();
        $table->string('phone')->nullable()->index();
        $table->string('password');
        $table->json('preferences')->nullable(); 
        $table->rememberToken();
        $table->softDeletes(); 
        $table->timestamps();
    });
    """

    # 3. Services Table
    migrations["create_services_table"] = """
    Schema::create('services', function (Blueprint $table) {
        $table->id();
        $table->string('name')->index();
        $table->unsignedInteger('duration_minutes');
        $table->unsignedInteger('cleanup_break_minutes')->default(0);
        $table->unsignedInteger('capacity')->default(1);
        $table->unsignedInteger('max_booking_days_advance')->default(7);
        $table->unsignedInteger('min_booking_notice_minutes')->default(60);
        $table->unsignedInteger('slot_interval_minutes')->default(15);
        $table->json('settings')->nullable(); // For future features like deposit requirements
        $table->boolean('is_active')->default(true);
        $table->softDeletes();
        $table->timestamps();
    });
    """

    # 4. Service Schedules (Recurring Weekly Patterns)
    migrations["create_service_schedules_table"] = """
    Schema::create('service_schedules', function (Blueprint $table) {
        $table->id();
        $table->foreignId('service_id')->constrained()->onDelete('cascade');
        $table->unsignedTinyInteger('day_of_week'); // 0-6
        $table->time('open_time');
        $table->time('close_time');
        $table->timestamps();

        $table->unique(['service_id', 'day_of_week']);
        $table->index(['service_id', 'day_of_week', 'open_time', 'close_time'], 'idx_service_hours');
    });
    """

    # 5. Service Breaks (Recurring Daily Interruptions like Lunch)
    migrations["create_service_breaks_table"] = """
    Schema::create('service_breaks', function (Blueprint $table) {
        $table->id();
        $table->foreignId('service_id')->constrained()->onDelete('cascade');
        $table->time('start_time');
        $table->time('end_time');
        $table->timestamps();

        $table->index(['service_id', 'start_time', 'end_time']);
    });
    """

    # 6. Polymorphic Exclusions (One-off/Non-recurring blocks)
    # Can target a Service, User (Staff), or any future resource.
    migrations["create_exclusions_table"] = """
    Schema::create('exclusions', function (Blueprint $table) {
        $table->id();
        $table->nullableMorphs('excludable'); // excludable_id and excludable_type
        $table->dateTime('start_at');
        $table->dateTime('end_at');
        $table->string('type')->default('holiday');
        $table->json('metadata')->nullable();
        $table->timestamps();

        $table->index(['excludable_type', 'excludable_id', 'start_at', 'end_at'], 'idx_exclusions_lookup');
    });
    """

    # 7. Appointments
    migrations["create_appointments_table"] = """
    Schema::create('appointments', function (Blueprint $table) {
        $table->id();
        $table->foreignId('service_id')->constrained();
        $table->foreignId('user_id')->constrained();
        $table->foreignId('staff_id')->nullable()->constrained('users');
        $table->dateTime('start_at');
        $table->dateTime('end_at');
        $table->unsignedInteger('slots_booked')->default(1);
        $table->string('status')->default('confirmed')->index();
        $table->json('custom_data')->nullable(); // For service-specific questions
        $table->softDeletes();
        $table->timestamps();

        // Index for capacity math and availability lookups
        $table->index(['service_id', 'status', 'start_at', 'end_at'], 'idx_capacity_check');
    });
    """

    return migrations

# Example usage:
all_migrations = generate_extensible_booking_system_migrations()
for name, code in all_migrations.items():
    print(f"--- Migration: {name} ---\n{code}")
```

### Flexibility and Future-Proofing Features

1.  **Polymorphic Exclusions**: By using `nullableMorphs`, the exclusion system is no longer hard-coded to specific tables. You can block time for a `Service` (e.g., "Salon Closed"), a `User` (e.g., "Expert on Leave"), or any new entity like a `Room` without changing the schema.
2.  **JSON Columns**: `settings` in `services` and `custom_data` in `appointments` allow you to store arbitrary data (e.g., specific intake questions or UI configuration) without adding new columns for every requirement change.
3.  **Soft Deletes**: Ensures that deleting a user or service doesn't break historical reporting, maintaining data integrity for past bookings.
4.  **Interval Management**: `slot_interval_minutes` allows the business to switch from 15-minute slots to 30-minute slots dynamically per service.
5.  **Optimized Indexing**: Composite indexes like `idx_capacity_check` and `idx_exclusions_lookup` ensure that availability queries remain fast even as the database grows.

To provide a schema that is both hyper-flexible and bulletproof against data integrity issues, I have designed a **Resource-Based Polymorphic Architecture**. This design uses polymorphic relations to handle complex scheduling and includes explicit database-level constraints to prevent invalid data.

